import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life", () => {
  it.todo("should return empty array for empty input -- []");
  it.todo(
    "should kill a single isolated live cell -- [(0,0)] becomes []",
  );
  it.todo(
    "should kill live cells with fewer than 2 neighbors (underpopulation) -- [(0,1), (1,1)] becomes []",
  );
  it.todo(
    "should birth a dead cell with exactly 3 live neighbors (reproduction) -- [(0,0), (1,0), (0,1)] becomes [(0,0), (1,0), (0,1), (1,1)]",
  );
  it.todo(
    "should keep live cells with 2 or 3 neighbors alive (survival) -- [(0,0), (1,0), (2,0), (1,2)] becomes [(1,0), (1,1)]",
  );
  it.todo(
    "should kill live cells with more than 3 neighbors (overpopulation) -- [(0,0), (1,0), (2,0), (1,1), (0,2), (1,2), (2,2)] becomes [(0,0), (2,0), (0,1), (2,1), (0,2), (2,2), (1,0), (1,2)]",
  );
  it.todo(
    "should leave a 2x2 block unchanged (still life) -- [(0,0), (1,0), (0,1), (1,1)] stays the same",
  );
  it.todo(
    "should oscillate a vertical blinker to horizontal -- [(0,0), (0,1), (0,2)] becomes [(-1,1), (0,1), (1,1)]",
  );
});

